        sleepingbag = { s = "Une piste de notes et de cachettes à travers quatre zones. Chaque étape est un objet à cliquer : aucun combat, aucun donneur de quête.", r = "Cozy Sleeping Bag (et en chemin un sac Old Toolbox, une arme à distance et plus encore)" },
        librarybooks = { s = "Retrouvez des livres de bibliothèque perdus dans le monde et rapportez-les. Chaque titre compte une fois ; les deux parcours réunis en font 20.", r = "Un charme de mage par livre ; à 10 livres un collier, à 20 un anneau (niveau 20), à 25 un arc, une main gauche ou une lumière au choix (niveau 40)" },
        onyxia = { s = "La longue suite qui vous ouvre le portail d'Onyxia. L'Alliance commence au niveau 48 dans les steppes Ardentes, la Horde au niveau 55 dans les Terres ingrates.", r = "Drakefire Amulet (à garder dans vos sacs pour entrer dans le repaire d'Onyxia)" },
        indreams = { s = "L'histoire de Tirion à travers les deux Maleterres, finissant par une escorte hors de Corvent. Étapes en groupe : Stratholme et l'escorte.", r = "Au choix : Mark of Fordring, Ornate Adamantium Breastplate, Fordring's Seal ou Shroud of the Exile" },
        darrowshire = { s = "La poupée de Pamela Sentiécarlate mène à Chromie à Andorhal et à un événement de groupe sur la place de Darrowshire.", r = "Au choix : Ring of Protection, Archlight Talisman ou Magebane Scion" },
        linken = { s = "Un paquet sur un radeau à Un'Goro lance un voyage par Berceau-de-l'Hiver, Gangrebois et Tanaris. Le dernier boss se fait mieux au niveau 55.", r = "Linken's Boomerang, plus Linken's Sword of Mastery ou Spirit of Aquementas" },
