        viper = { s = "Portez les cinq pièces Croc des cavernes des Lamentations et votre forme de félin devient un serpent. L'ensemble peut aussi étourdir.", r = "Forme de félin serpent tant que vous portez l'ensemble complet" },
        wolfsbane = { s = "Une suite pour paladin réprouvé avec des étapes aux Mortemines, sur le rivage de Brassenoire et au donjon d'Ombrecroc. Apprenez d'abord les épées à deux mains.", r = "Wolfsbane, une épée à deux mains rare qui frappe fort les loups et les worgens" },
