        malignantroot = { s = "Le Nightveiled Rotheap ne parcourt les Paluns que la nuit (heure du serveur). Ses entrailles peuvent être envoyées à un autre personnage.", r = "Malignant Root, un anneau rare sans niveau requis" },
        sander = { s = "Une carte au trésor des murlocs côtiers de la marche de l'Ouest mène à quatre endroits.", r = "Captain Sander's Locker (un sac), chemise, ceinture et une barre d'argent" },
        strahnbrad = { s = "Une note rare du Syndicat à Strahnbrad. Le Choc de flammes d'un mage réveille un élémentaire de feu. Acceptez la quête avant de le tuer.", r = "Brilliant Cloak, argent et expérience" },
        faithful = { s = "Espionnez une secte sur l'île de Zephras, caché derrière une armoire.", r = "Armes et armures au choix, réputation auprès des Windshaper" },
        applejack = { s = "Brassez du Thunder Applejack avec quatre pommes dans un alambic caché près des chutes du Tonnerre.", r = "Thunder Applejack et la quête An Apple Treat" },
