        whimsyfin = { s = "Une recette de cuisine des Carmines (Cuisine 85) qui vous change en ninja ou pirate orc pendant une heure.", r = "Savory Whimsyfin Delight (déguisement aléatoire de ninja ou de pirate orc)" },
        gustjumper = { s = "Chantez pour les grenouilles près d'une cascade de l'île de Zephras.", r = "Mascotte Musical Gustjumper" },
